<?php

declare(strict_types=1);namespace backend\controllers;use backend\components\AdminController;use common\models\News;use Yii;use yii\data\ActiveDataProvider;use yii\web\NotFoundHttpException;
final class NewsController extends AdminController { protected string $permission='manageContent'; public function actionIndex():string{return $this->render('index',['dataProvider'=>new ActiveDataProvider(['query'=>News::find()->orderBy(['id'=>SORT_DESC])])]);}public function actionCreate(){return $this->edit(new News(['published'=>0,'author_id'=>Yii::$app->user->id]));}public function actionUpdate(int $id){return $this->edit($this->find($id));}public function actionDelete(int $id){if(Yii::$app->request->isPost)$this->find($id)->delete();return $this->redirect(['index']);}private function edit(News $m){if($m->load(Yii::$app->request->post())&&$m->save())return $this->redirect(['index']);return $this->render('form',['model'=>$m]);}private function find(int $id):News{$m=News::findOne($id);if(!$m)throw new NotFoundHttpException();return $m;}}
